CREATE TABLE IF NOT EXISTS schema_migrations(name text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id text PRIMARY KEY, email text NOT NULL UNIQUE, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('asistente','staff','organizador','admin')), name text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions(id uuid PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), refresh_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, revoked_at timestamptz, family_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_family ON sessions(family_id);
CREATE TABLE seed_metadata(key text PRIMARY KEY, value text NOT NULL);
CREATE TABLE events(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code text UNIQUE, name text NOT NULL, organizer_id text NOT NULL REFERENCES users(id), starts_at timestamptz NOT NULL, sale_opens_at timestamptz NOT NULL, refund_until timestamptz NOT NULL, per_account_limit integer NOT NULL CHECK(per_account_limit>0), status text NOT NULL DEFAULT 'en_venta', venue text NOT NULL DEFAULT '');
CREATE INDEX events_order ON events(starts_at,id);
CREATE TABLE zones(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, event_id integer NOT NULL REFERENCES events(id), name text NOT NULL, capacity integer NOT NULL CHECK(capacity>0), sold_count integer NOT NULL DEFAULT 0 CHECK(sold_count>=0), reserved_count integer NOT NULL DEFAULT 0 CHECK(reserved_count>=0), CHECK(sold_count+reserved_count<=capacity), UNIQUE(event_id,name));
CREATE INDEX zones_event ON zones(event_id);
CREATE TABLE price_phases(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, zone_id integer NOT NULL REFERENCES zones(id), name text NOT NULL, price_cents integer NOT NULL CHECK(price_cents>=0), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, CHECK(ends_at>starts_at));
CREATE INDEX price_phase_current ON price_phases(zone_id,starts_at DESC,ends_at);
CREATE TABLE gates(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,event_id integer NOT NULL REFERENCES events(id),name text NOT NULL,zone_id integer REFERENCES zones(id));
CREATE TABLE staff_assignments(event_id integer NOT NULL REFERENCES events(id),user_id text NOT NULL REFERENCES users(id),PRIMARY KEY(event_id,user_id));
CREATE TABLE account_inventory(user_id text NOT NULL REFERENCES users(id), event_id integer NOT NULL REFERENCES events(id), paid_count integer NOT NULL DEFAULT 0 CHECK(paid_count>=0), reserved_count integer NOT NULL DEFAULT 0 CHECK(reserved_count>=0), PRIMARY KEY(user_id,event_id));
CREATE TABLE reservations(id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), event_id integer NOT NULL REFERENCES events(id), zone_id integer NOT NULL REFERENCES zones(id), quantity integer NOT NULL CHECK(quantity>0), unit_price_cents integer NOT NULL CHECK(unit_price_cents>=0), amount_cents integer NOT NULL CHECK(amount_cents>=0), state text NOT NULL CHECK(state IN ('active','paid','expired','cancelled')), expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX reservations_expiry ON reservations(expires_at,zone_id) WHERE state='active';
CREATE INDEX reservations_user ON reservations(user_id,created_at DESC,id);
CREATE TABLE purchases(id text PRIMARY KEY, reservation_id text UNIQUE REFERENCES reservations(id), user_id text NOT NULL REFERENCES users(id), event_id integer NOT NULL REFERENCES events(id), zone_id integer NOT NULL REFERENCES zones(id), quantity integer NOT NULL, unit_price_cents integer NOT NULL, amount_cents integer NOT NULL CHECK(amount_cents>=0), state text NOT NULL, paid_at timestamptz NOT NULL DEFAULT now(), refunded_at timestamptz);
CREATE TABLE tickets(id text PRIMARY KEY, purchase_id text NOT NULL REFERENCES purchases(id), event_id integer NOT NULL REFERENCES events(id), zone_id integer NOT NULL REFERENCES zones(id), holder_id text NOT NULL REFERENCES users(id), buyer_id text NOT NULL REFERENCES users(id), state text NOT NULL CHECK(state IN ('paid','transferred','used','refunded','void')), version integer NOT NULL DEFAULT 1 CHECK(version>0), holder_public_key text, issued_at timestamptz NOT NULL DEFAULT now(), used_at timestamptz);
CREATE INDEX tickets_holder_cursor ON tickets(holder_id,issued_at DESC,id);
CREATE INDEX tickets_buyer_event ON tickets(buyer_id,event_id,state);
CREATE TABLE transfers(id text PRIMARY KEY, ticket_id text NOT NULL REFERENCES tickets(id), from_user_id text NOT NULL REFERENCES users(id), to_user_id text NOT NULL REFERENCES users(id), state text NOT NULL CHECK(state IN ('pending','accepted','cancelled')), created_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz);
CREATE UNIQUE INDEX transfers_pending ON transfers(ticket_id) WHERE state='pending';
CREATE TABLE payment_ledger(id text PRIMARY KEY, reservation_id text REFERENCES reservations(id),ticket_id text REFERENCES tickets(id), user_id text NOT NULL REFERENCES users(id), kind text NOT NULL CHECK(kind IN ('charge','refund','late_refund')), amount_cents integer NOT NULL CHECK(amount_cents>=0),created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX payment_charge_once ON payment_ledger(reservation_id) WHERE kind='charge';
CREATE UNIQUE INDEX payment_late_once ON payment_ledger(reservation_id) WHERE kind='late_refund';
CREATE UNIQUE INDEX payment_refund_once ON payment_ledger(ticket_id) WHERE kind='refund';
CREATE TABLE idempotency(user_id text NOT NULL REFERENCES users(id), operation text NOT NULL, key text NOT NULL, fingerprint text NOT NULL,response jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,operation,key));
CREATE TABLE revocations(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,ticket_id text NOT NULL REFERENCES tickets(id),version integer NOT NULL,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX revocations_ticket ON revocations(ticket_id,version);
CREATE TABLE audit_log(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, actor_id text REFERENCES users(id),action text NOT NULL,resource text NOT NULL,reason text,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_log_cursor ON audit_log(id DESC);
CREATE FUNCTION immutable_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'audit log is append-only'; END $$;
CREATE TRIGGER audit_no_change BEFORE UPDATE OR DELETE ON audit_log FOR EACH ROW EXECUTE FUNCTION immutable_audit();
